import { useEffect } from "react"

import AmbientEnvironment from "../environment/AmbientEnvironment"
import CommandCenter from "../components/CommandCenter"
import ContextPanel from "../components/ContextPanel"
import ObservatoryRail from "../components/ObservatoryRail"
import { ObservatoryRouter } from "../observatories"
import { useWorkspaceStore } from "../state/workspace-store"
import { useLayoutStore } from "../state/layout-store"
import { Panel, PanelGroup, PanelResizeHandle } from "react-resizable-panels"

export default function CognitiveShell() {
  const { active, setCommandOpen } = useWorkspaceStore()
  const { left, center, right, save } = useLayoutStore()

  useEffect(() => {
    const handler = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault()
        setCommandOpen(true)
      }
    }

    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [setCommandOpen])

  return (
    <main className="shell">
      <AmbientEnvironment />
      <CommandCenter />

      <div className="top-strip" role="banner" aria-label="Palaver status">
        <div className="identity">Palaver Workstation</div>
        <div className="controls">
          <span className="pill" title="Active observatory">{active}</span>
        </div>
      </div>

      <PanelGroup
        direction="horizontal"
        onLayout={(sizes) => {
          // sizes array is [left, center, right]
          if (!Array.isArray(sizes) || sizes.length !== 3) return
          save(sizes[0], sizes[1], sizes[2])
        }}
        style={{ flex: 1, minHeight: 0 }}
      >
        <Panel defaultSize={left} minSize={12}>
          <aside className="palaver-left" style={{ height: "100%" }}>
            <ObservatoryRail />
          </aside>
        </Panel>

        <PanelResizeHandle />

        <Panel defaultSize={center} minSize={40}>
          <section className="palaver-center" style={{ height: "100%", minWidth: 0 }}>
            {ObservatoryRouter(active)}
          </section>
        </Panel>

        <PanelResizeHandle />

        <Panel defaultSize={right} minSize={12}>
          <aside className="palaver-right" style={{ height: "100%" }}>
            <ContextPanel />
          </aside>
        </Panel>
      </PanelGroup>
    </main>
  )
}

