import { Command } from "cmdk"
import {
  Observatory,
  useWorkspaceStore
} from "../state/workspace-store"
import { useLayoutStore } from "../state/layout-store"
import { useMemo, useState, useEffect } from "react"

const observatories: { id: Observatory; label: string }[] = [
  { id: "graph", label: "Graph" },
  { id: "authority", label: "Authority" },
  { id: "lineage", label: "Lineage" },
  { id: "dependency", label: "Dependency" },
  { id: "relationship", label: "Relations" },
  { id: "timeline", label: "Timeline" },
  { id: "repository", label: "Repository" },
  { id: "memory", label: "Memory" },
  { id: "ontology", label: "Ontology" },
  { id: "fields", label: "Fields" }
]

type Action = {
  id: string
  label: string
  run: () => void
  group: string
}

export default function CommandCenter() {
  const { commandOpen, setCommandOpen, setActive } = useWorkspaceStore()
  const { left, center, right, save } = useLayoutStore()
  const [query, setQuery] = useState("")

  const actions = useMemo<Action[]>(() => {
    const nav: Action[] = observatories.map((o) => ({
      id: `nav:${o.id}`,
      label: `Go to ${o.label}`,
      run: () => setActive(o.id),
      group: "Navigate"
    }))

    const layout: Action[] = [
      {
        id: "layout:reset-panels",
        label: "Reset panel sizes",
        run: () => save(18, 64, 18),
        group: "Layout"
      },
      {
        id: "layout:widen-center",
        label: "Widen center",
        run: () => {
          // naive: add 8 to center, deduct 4/4 from sides (clamped)
          const nc = Math.min(84, center + 8)
          const shrink = Math.min(4, Math.max(0, (nc - center) / 2))
          const nl = Math.max(8, left - shrink)
          const nr = Math.max(8, right - shrink)
          save(nl, nc, nr)
        },
        group: "Layout"
      },
      {
        id: "layout:widen-right",
        label: "Widen right",
        run: () => {
          const nr = Math.min(40, right + 6)
          const nc = Math.max(32, center - 6)
          save(left, nc, nr)
        },
        group: "Layout"
      }
    ]

    return [...nav, ...layout]
  }, [setActive, left, center, right, save])

  useEffect(() => {
    if (!commandOpen) setQuery("")
  }, [commandOpen])

  if (!commandOpen) return null

  return (
    <div
      className="command-backdrop"
      onClick={() => setCommandOpen(false)}
    >
      <Command
        className="command-center"
        onClick={(event) => event.stopPropagation()}
        filter={(value, search) => (value.toLowerCase().includes(search.toLowerCase()) ? 1 : 0)}
        shouldFilter={true}
      >
        <Command.Input placeholder="Type a command…" value={query} onValueChange={setQuery} />
        <Command.Empty>No commands.</Command.Empty>
        <Command.List>
          {Array.from(new Set(actions.map((a) => a.group))).map((group) => (
            <Command.Group key={group} heading={group}>
              {actions
                .filter((a) => a.group === group)
                .map((action) => (
                  <Command.Item
                    key={action.id}
                    onSelect={() => {
                      action.run()
                      setCommandOpen(false)
                    }}
                  >
                    {action.label}
                  </Command.Item>
                ))}
            </Command.Group>
          ))}
        </Command.List>
      </Command>
    </div>
  )
}

